/* @lc app=leetcode id=3486 lang=kotlin */ class Solution { fun longestSpecialPath(edges: Array<IntArray>, nums: IntArray): IntArray = nums.size.let { n -> edges.flatMap { (a, b, w) -> listOf(a to (b to w), b to (a to w)) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(50001) { -1 }.let { last -> IntArray(n).let { dep -> IntArray(n).let { sv -> IntArray(n).let { t1 -> IntArray(n).let { t2 -> IntArray(n).let { pd -> IntArray(n).let { wt -> IntArray(n) { -1 }.also { it[0] = 0 }.let { par -> java.util.ArrayDeque<Int>().also { it.addFirst(0) }.let { st -> generateSequence { st.pollFirst() }.mapNotNull { e -> if (e >= 0) par[e].let { p -> (if (e == 0) 0 else dep[p] + 1).let { d -> (if (e == 0) -1 else t1[p]).let { a1 -> (if (e == 0) -1 else t2[p]).let { a2 -> last[nums[e]].let { ev -> dep.set(e, d).also { pd[d] = if (e == 0) 0 else pd[dep[p]] + wt[e] }.also { sv[e] = ev }.also { t1[e] = maxOf(a1, ev) }.also { t2[e] = if (ev > a1) a1 else maxOf(a2, ev) }.also { last[nums[e]] = d }.also { st.addFirst(e.inv()) }.also { g[e].orEmpty().filter { (v, _) -> par[v] == -1 }.forEach { (v, w) -> par[v] = e.also { wt[v] = w }.also { st.addFirst(v) } } }.let { (pd[d] - pd[t2[e] + 1]) to (d - t2[e]) } } } } } } else last.set(nums[e.inv()], sv[e.inv()]).let { null } }.fold(0 to 1) { b, c -> if (c.first > b.first || (c.first == b.first && c.second < b.second)) c else b }.let { intArrayOf(it.first, it.second) } } } } } } } } } } } } }